-- 421_intake_xjz_executable_item_effect_candidates.sql
-- Purpose: intake client-recovered executable item effect candidates without persisting raw description payloads.
-- Boundary: client-recovered handler candidates are not official packet proof. Runtime application must still respect existing server validation.

CREATE TABLE IF NOT EXISTS god2_research.xjz_executable_item_effect_candidates (
  item_id INT NOT NULL,
  item_code VARCHAR(64) NULL,
  item_prefix VARCHAR(32) NOT NULL,
  name_zh_tw VARCHAR(128) NOT NULL,
  handler_name VARCHAR(64) NOT NULL,
  target_type VARCHAR(64) NOT NULL,
  handler_param_json TEXT NOT NULL,
  effect_code VARCHAR(64) NULL,
  effect_description_zh_tw VARCHAR(256) NULL,
  source_line INT NULL,
  evidence_status VARCHAR(64) NOT NULL,
  packet_evidence_boundary TINYINT NOT NULL,
  source_pack_id VARCHAR(96) NOT NULL,
  created_at_utc TIMESTAMP NOT NULL DEFAULT UTC_TIMESTAMP(),
  PRIMARY KEY (item_id),
  KEY idx_xjz_item_effect_candidate_handler (handler_name),
  KEY idx_xjz_item_effect_candidate_effect_code (effect_code),
  KEY idx_xjz_item_effect_candidate_pack (source_pack_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS god2_research.xjz_executable_item_effect_candidate_summary (
  handler_name VARCHAR(64) NOT NULL,
  candidate_count INT NOT NULL,
  linked_formal_item_count INT NOT NULL,
  packet_boundary_count INT NOT NULL,
  game_function_zh_tw VARCHAR(128) NOT NULL,
  server_action_zh_tw VARCHAR(256) NOT NULL,
  source_pack_id VARCHAR(96) NOT NULL,
  PRIMARY KEY (handler_name, source_pack_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TEMPORARY TABLE IF EXISTS xjz_executable_item_rule_stage;
CREATE TEMPORARY TABLE xjz_executable_item_rule_stage (
  item_id INT NOT NULL PRIMARY KEY,
  item_code TEXT NULL,
  item_prefix TEXT NOT NULL,
  name_zh_tw TEXT NOT NULL,
  handler_name TEXT NOT NULL,
  target_type TEXT NOT NULL,
  param_json TEXT NOT NULL,
  effect_code TEXT NULL,
  effect_description_zh_tw TEXT NULL,
  raw_description_json TEXT NOT NULL,
  raw_source TEXT NOT NULL,
  raw_line INT NULL,
  evidence_status TEXT NOT NULL,
  packet_evidence_boundary INT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DELETE FROM god2_research.xjz_executable_item_effect_candidates
WHERE source_pack_id='XJZ-csharp-evidence-capture-pack-20260818';
SELECT item_id,item_code,item_prefix,name_zh_tw,handler_name,target_type,param_json,effect_code,effect_description_zh_tw,raw_line,evidence_status,packet_evidence_boundary,'XJZ-csharp-evidence-capture-pack-20260818'
FROM xjz_executable_item_rule_stage;

DELETE FROM god2_research.xjz_executable_item_effect_candidate_summary
WHERE source_pack_id='XJZ-csharp-evidence-capture-pack-20260818';
SELECT candidate.handler_name,
       COUNT(*) AS candidate_count,
       SUM(CASE WHEN formal_item.item_id IS NULL THEN 0 ELSE 1 END) AS linked_formal_item_count,
       SUM(candidate.packet_evidence_boundary) AS packet_boundary_count,
       CASE candidate.handler_name
           WHEN 'restore_hp' THEN '補血道具'
           WHEN 'restore_mp' THEN '補魔道具'
           WHEN 'restore_hp_mp' THEN '補血補魔道具'
           WHEN 'clear_status' THEN '解除異常狀態道具'
           WHEN 'apply_stat_buff' THEN '能力提升藥品'
           WHEN 'learn_skill' THEN '學習技能道具'
           WHEN 'teleport' THEN '傳送道具'
           WHEN 'feed_pet_or_mount' THEN '餵食寵物或坐騎道具'
           ELSE '其他道具效果'
       END AS game_function_zh_tw,
       CASE candidate.handler_name
           WHEN 'restore_hp' THEN '可比對 ItemUseEffectEngine 補 HP handler 後導入。'
           WHEN 'restore_mp' THEN '可比對 ItemUseEffectEngine 補 MP handler 後導入。'
           WHEN 'restore_hp_mp' THEN '可比對 ItemUseEffectEngine 補 HP/MP handler 後導入。'
           WHEN 'clear_status' THEN '可比對狀態效果系統後導入解除異常。'
           WHEN 'apply_stat_buff' THEN '可比對 Buff/回合持續時間規則後導入。'
           WHEN 'learn_skill' THEN '需比對技能書與角色技能狀態後導入。'
           WHEN 'teleport' THEN '需補正式地圖與傳送封包驗證後導入。'
           WHEN 'feed_pet_or_mount' THEN '需比對寵物/坐騎忠誠與餵食規則後導入。'
           ELSE '保留候選，待服務端 handler 對照。'
       END AS server_action_zh_tw,
       'XJZ-csharp-evidence-capture-pack-20260818'
FROM god2_research.xjz_executable_item_effect_candidates candidate
LEFT JOIN god2_game.items formal_item ON formal_item.item_id=candidate.item_id
WHERE candidate.source_pack_id='XJZ-csharp-evidence-capture-pack-20260818'
GROUP BY candidate.handler_name;

UPDATE god2_research.xjz_csharp_apply_queue
SET safe_apply_level_zh_tw='已建立 1664 筆可執行候選，正式套用仍需 handler 對照',
    next_server_action_zh_tw='從 xjz_executable_item_effect_candidate_summary 依 handler 分批接到 ItemUseEffectEngine；補血補魔與解除狀態優先，傳送與餵食需要更多封包或黑箱測試。'
WHERE queue_key='item_effect_rules'
  AND source_pack_id='XJZ-csharp-evidence-capture-pack-20260818';

DROP TEMPORARY TABLE IF EXISTS xjz_executable_item_rule_stage;
